arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Authorization: Bearer <TOKEN>' --data 'exclude_archived=true&types=public_channel,private_channel&limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(1)
for c in d['channels']:
    if 'incident' in c['name'].lower():
        print(json.dumps({'id':c['id'],'name':c['name'],'topic':(c.get('topic') or {}).get('title',''),'is_private':c.get('is_private',False)}))
"

